import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != c.owner());
        vm.assume(caller.balance == 0);

        // Fund the contract
        vm.deal(address(uint160(uint256(keccak256(abi.encode(caller, block.timestamp))))), 1 ether);
        vm.prank(address(uint160(uint256(keccak256(abi.encode(caller, block.timestamp))))));
        (bool sent,) = address(c).call{value: 1 ether}("");
        require(sent, "funding failed");

