pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, address ownerSeed, address senderWithValue) public {
        // Derive a consistent owner address from fuzzed seed to avoid casting the seed directly as owner (which could collide with predeployed addresses)
        address OWNER = address(uint160(uint256(keccak256(abi.encode(ownerSeed)))));
        vm.assume(OWNER != address(0));
        vm.assume(amount > 0 && amount <= address(this).balance);

        // Deploy an adversarial callee whose receive() always reverts, simulating an owner that cannot receive ETH.
        RevertingReceiver reverter = new RevertingReceiver();
        address adversarialOwner = address(reverter);
        // Ensure adversarial owner is distinct from the derived OWNER
        vm.assume(adversarialOwner != OWNER);

        // Fund the test contract so it can forward ETH to C
        vm.deal(address(this), amount);

        // Deploy fresh C with the adversarial owner
        vm.prank(adversarialOwner);
        c = new C();

        // Give C some ETH by sending through fallback from a pranked caller
        vm.deal(senderWithValue, amount);
        vm.prank(senderWithValue);
        (bool s, ) = address(c).call{value: amount}("");
        require(s, "funding failed");

        uint256 balanceBefore = address(c).balance;
        require(balanceBefore == amount, "balance mismatch");

        // Record adversarial owner ETH balance before
        uint256 ownerBalanceBefore = adversarialOwner.balance;

        // Attempt withdrawAll as adversarialOwner
        bool ok = false;
        vm.prank(adversarialOwner);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balanceAfter = address(c).balance;
        uint256 ownerBalanceAfter = adversarialOwner.balance;

        // The property:
        // If the transfer to the owner succeeds (ok == true), the contract balance MUST become zero AND the owner's balance MUST increase by exactly the prior contract balance.
        // If the transfer reverts (ok == false), the contract balance MUST remain unchanged AND the owner's balance MUST remain unchanged.
        // The buggy version never transfers ETH, so for the adversarial owner that reverts, ok==false is reached and property (2) is satisfied,
        // BUT for the non-adversarial OWNER that can receive ETH, property (1) is violated because withdrawAll does nothing.
        // We therefore test the property using the adversarial owner: for both correct and buggy, ok is false, so property (2) holds. That test would pass on both.
        // We need to test the property using the non-adversarial (normal) owner to catch the bug.
        // Let's redesign: use the derived OWNER as the actual owner, and show that the reference satisfies (1) while the buggy does not.
        // We must have TWO deployments: one with normal owner (OWNER) and one with adversarial. But we can only assert on c.
        // This approach repeats the already-tried property. Instead, we formulate a property that always holds for the correct contract regardless of owner's receiving capability,
        // but fails for the buggy one when owner can receive ETH.
        // Property: after withdrawAll, (balanceAfter == 0) == (ok == true) && ownerBalanceAfter - ownerBalanceBefore == (ok ? balanceBefore : 0).
        // For the buggy, balanceAfter == balanceBefore and ownerBalanceAfter == ownerBalanceBefore even when ok==true (if owner can receive ETH),
        // so the condition fails for a non-reverting owner.
        // Therefore we need to test with a normal owner (OWNER) that CAN receive ETH. We'll deploy C with OWNER as owner, fund it, and test.
    }
}

